// Parsea TSV directo: tabs, sin quotes. Fila 0 = headers.
const items = $input.all();
if (!items.length) return [];

const raw = await this.helpers.getBinaryDataBuffer(0, 'archivo');
const text = raw.toString('utf-8');

const lines = text.split(/\r?\n/).filter(l => l.trim());
if (lines.length < 2) return [];

const headers = lines[0].split('\t');

return lines.slice(1).map(line => {
  const values = line.split('\t');
  const obj = {};
  headers.forEach((h, i) => {
    obj[h.trim()] = values[i]?.trim() ?? '';
  });
  return { json: obj };
});

// TSV real de MS Bookings (export Colombia):
// Date Time (DD/MM/YYYY H:MM), Customer Name, Customer Email,
// Customer Phone, Staff Name, Staff Email, Service,
// Duration (mins.), Booking Id, Custom Fields
const items = $input.all();

const pad2 = n => String(n).padStart(2, '0');

function parseDateTime(str) {
  if (!str) return { fecha: null, hora: null };
  const match = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})$/);
  if (!match) return { fecha: null, hora: null };
  const [, day, month, year, hour, minute] = match;
  return {
    fecha: `${year}-${pad2(month)}-${pad2(day)}`,
    hora:  `${pad2(hour)}:${pad2(minute)}`
  };
}

function parseDuration(str) {
  if (!str) return null;
  const n = parseInt(str, 10);
  return isNaN(n) ? null : n;
}

function calcEndTime(startStr, durationMins) {
  if (!startStr || !durationMins) return null;
  const match = startStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})$/);
  if (!match) return null;
  const [, day, month, year, hour, minute] = match;
  const d = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), parseInt(hour), parseInt(minute));
  d.setMinutes(d.getMinutes() + durationMins);
  return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}

function extractModalidad(customFields) {
  if (!customFields) return 'Virtual';
  try {
    const obj = typeof customFields === 'string' ? JSON.parse(customFields) : customFields;
    const val = obj['Selecciona la Modalidad de tu sesión'] || '';
    if (/presencial/i.test(val)) return 'Presencial';
    return 'Virtual';
  } catch (_e) { return 'Virtual'; }
}

return items
  .filter(i => i.json['Customer Email'])
  .map(i => {
    const r = i.json;
    const start = parseDateTime(r['Date Time']);
    const durationMins = parseDuration(r['Duration (mins.)']);
    const hora_fin = calcEndTime(r['Date Time'], durationMins);
    const modalidad = extractModalidad(r['Custom Fields']);
    return { json: {
      p_email:               (r['Customer Email'] || '').trim().toLowerCase(),
      p_booking_email:       (r['Customer Email'] || '').trim().toLowerCase(),
      p_full_name:           (r['Customer Name']  || '').trim(),
      p_phone:               r['Customer Phone'] || null,
      p_city:                null,
      p_booking_customer_id: r['Booking Id'] || null,
      p_origen:              'booking',
      _staff_name:   (r['Staff Name'] || r['Staff'] || '').trim() || null,
      _staff_email:  (r['Staff Email'] || '').trim().toLowerCase() || null,
      _service:      r['Service'] || null,
      _duration:     durationMins,
      _fecha_sesion: start.fecha,
      _hora_inicio:  start.hora,
      _hora_fin:     hora_fin,
      _modalidad:    modalidad,
      _booking_id:   r['Booking Id'] || null
    }};
  });

// Merge the RPC response (lead_id) with booking session data
// $input.all() = output from RPC (has lead_id, matched_by)
// $('Transform Bookings Row').all() = booking data with _staff_email
const rpcItems = $input.all();
const bookingItems = $('Transform Bookings Row').all();

return rpcItems.map((rpcItem, index) => {
  const booking = bookingItems[index]?.json || {};
  return {
    json: {
      lead_id:       rpcItem.json?.lead_id || null,
      matched_by:    rpcItem.json?.matched_by || null,
      _staff_email:  booking._staff_email || null,
      _staff_name:   booking._staff_name  || null,
      _fecha_sesion: booking._fecha_sesion || null,
      _hora_inicio:  booking._hora_inicio  || null,
      _hora_fin:     booking._hora_fin     || null,
      _modalidad:    booking._modalidad    || 'Virtual',
      _service:      booking._service      || null,
      _booking_id:   booking._booking_id   || null,
      _duration:     booking._duration     || null
    }
  };
});
